let source='upload';const LIMIT=100_000_000;
const formatGroups={video:[['mp4','MP4'],['mkv','Matroska'],['webm','WebM'],['mov','QuickTime'],['avi','AVI'],['m4v','M4V']],audio:[['mp3','MP3'],['wav','WAV · Sıkıştırılmamış'],['flac','FLAC · Kayıpsız'],['aac','AAC'],['ogg','Ogg Vorbis'],['m4a','M4A']]};
let kind='video';const lastFormats={video:'mp4',audio:'mp3'};
function isVideoOutput(value){return formatGroups.video.some(([extension])=>extension===value)}
function qualityOptions(value){return isVideoOutput(value)?[['1080','1080p · Full HD'],['720','720p · HD'],['480','480p'],['360','360p']]:['wav','flac'].includes(value)?[['source',value==='wav'?'PCM · Sıkıştırılmamış':'FLAC · Kayıpsız']]:value==='mp3'?[['320','320 kbps · En yüksek'],['192','192 kbps · Standart'],['128','128 kbps · Küçük dosya']]:[['256','256 kbps · Yüksek'],['192','192 kbps · Standart'],['128','128 kbps · Küçük dosya']]}
function setKind(value){if(busy)return;kind=value;$('#video-kind').setAttribute('aria-pressed',String(kind==='video'));$('#audio-kind').setAttribute('aria-pressed',String(kind==='audio'));$('#output-format').innerHTML=formatGroups[kind].map(([ext,label])=>'<option value="'+ext+'">.'+ext+' — '+label+'</option>').join('');$('#output-format').value=lastFormats[kind];$('#output-format').dispatchEvent(new Event('change'));if(isVideoOutput(format))$('#quality').value='480'}
$('#video-kind').onclick=()=>setKind('video');$('#audio-kind').onclick=()=>setKind('audio');
function updateAction(){const extension=format.toUpperCase(),type=isVideoOutput(format)?' video':' ses';$('#submit span').textContent=source==='upload'?extension+' olarak dönüştür':extension+' indir';$('.choose-heading h2').textContent=source==='upload'?'Hangi uzantıya dönüştürelim?':'Hangi uzantıyla indirelim?';$('#format-help').textContent=(source==='upload'?'Seçtiğin dosya '+extension+type+' olarak dönüştürülecek.':'YouTube bağlantısından '+extension+type+' dosyası indirilecek.')+(['wav','flac'].includes(format)?' Kaynak sesin kalitesi yükseltilmez.':'')}
$('#output-format').onchange=()=>{format=$('#output-format').value;lastFormats[kind]=format;$('#quality').innerHTML=qualityOptions(format).map(([value,label])=>'<option value="'+value+'">'+label+'</option>').join('');updateAction()};
function setSource(value){if(busy)return;source=value;for(const name of ['upload','youtube']){const selected=name===source;$('#'+name+'-tab').setAttribute('aria-selected',String(selected));$('#'+name+'-tab').tabIndex=selected?0:-1;$('#'+name+'-panel').hidden=!selected}$('#url').disabled=source!=='youtube';$('#url').required=source==='youtube';$('#file').disabled=source!=='upload';$('#file').required=source==='upload';updateAction();$('h1').innerHTML=source==='upload'?'Dosyanı seç.<br><span>Formatını değiştir.</span>':'Bağlantıyı yapıştır.<br><span>Gerisi kolay.</span>';$('.eyebrow').lastChild.textContent=source==='upload'?' KENDİ DOSYAN, İSTEDİĞİN FORMAT':' YOUTUBE’DAN CİHAZINA';$('.intro').innerHTML=source==='upload'?'Video ve sesini istediğin formata dönüştür.<br>Kendi dosyalarınla, ücretsiz başla.':'Videonu izle. Müziğini yanında taşı.<br>Bir bağlantı, iki format.';$('.how>div:first-child p').innerHTML=source==='upload'?'Dosyanı seç<small>Video veya ses dosyanı yükle.</small>':'Bağlantıyı kopyala<small>YouTube’da videonu aç.</small>';$('#status').hidden=true;$('#save').hidden=true;$('#progress-wrap').hidden=true}
for(const name of ['upload','youtube']){$('#'+name+'-tab').onclick=()=>setSource(name);$('#'+name+'-tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'upload':e.key==='End'?'youtube':source==='upload'?'youtube':'upload';setSource(next);$('#'+next+'-tab').focus()}}}
function fileChanged(){const file=$('#file').files[0];$('#file-name').textContent=file?file.name:'Video veya ses dosyası seç';$('#file-meta').textContent=file?(file.size>=1_000_000_000?(file.size/1_000_000_000).toFixed(2)+' GB':(file.size/1_000_000).toFixed(1)+' MB')+' · Sınır: 100 MB':'Ücretsiz · Dosya başına en fazla 100 MB';if(file?.size>LIMIT)status('Dosya yükleme sınırı 100 MB. Daha küçük bir dosya seç.',true);else $('#status').hidden=true}
$('#file').onchange=fileChanged;
for(const event of ['dragenter','dragover'])$('#dropzone').addEventListener(event,e=>{e.preventDefault();if(!busy)$('#dropzone').classList.add('dragging')});
for(const event of ['dragleave','drop'])$('#dropzone').addEventListener(event,e=>{e.preventDefault();$('#dropzone').classList.remove('dragging')});
$('#dropzone').addEventListener('drop',e=>{if(busy)return;if(e.dataTransfer.files.length!==1){status('Her işlem için tek bir dosya seç.',true);return}$('#file').files=e.dataTransfer.files;fileChanged()});
function lock(value){busy=value;document.querySelectorAll('#form input,#form button,#form select,.source-tabs button').forEach(el=>el.disabled=value);if(!value){$('#url').disabled=source!=='youtube';$('#file').disabled=source!=='upload'}}
function upload(file,selectedFormat,quality){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/convert?rightsConfirmed=true&format='+selectedFormat+'&quality='+quality);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.timeout=0;xhr.upload.onprogress=e=>{if(e.lengthComputable){$('#progress').value=e.loaded/e.total*100;status('Dosya yükleniyor… %'+Math.round(e.loaded/e.total*100))}};xhr.onload=()=>{let data;try{data=JSON.parse(xhr.responseText)}catch{reject(Error('Hizmetten yanıt alınamadı.'));return}xhr.status<300?resolve(data):reject(Error(data.error||'Dosya yüklenemedi.'))};xhr.onerror=()=>reject(Error('Yükleme bağlantısı kesildi. Dosya sınırı 100 MB; bağlantını da kontrol et.'));xhr.ontimeout=()=>reject(Error('Yükleme zaman aşımına uğradı.'));xhr.send(file)})}
$('#form').onsubmit=async e=>{e.preventDefault();if(busy)return;const file=$('#file').files[0],url=videoURL($('#url').value.trim());if(source==='upload'&&(!file||!file.size||file.size>LIMIT)){status('Boş olmayan, en fazla 100 MB bir dosya seç.',true);return}if(source==='youtube'&&!url){status('Geçerli bir YouTube video bağlantısı gir.',true);return}if(!$('#rights-confirmed').checked){status('İçeriği işleme iznini onayla.',true);return}const selectedFormat=format,quality=$('#quality').value;lock(true);$('#save').hidden=true;$('#progress-wrap').hidden=false;$('#progress').removeAttribute('value');status(source==='upload'?'Dosya yükleniyor…':'Video bilgileri alınıyor…');try{let job;if(source==='upload')job=await upload(file,selectedFormat,quality);else{const r=await fetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url,format:selectedFormat,quality,rightsConfirmed:true})});job=await r.json();if(!r.ok)throw Error(job.error||'İndirme başlatılamadı.')}$('#progress').removeAttribute('value');status('Dosya hazırlanıyor…');const deadline=Date.now()+22*60*1000;while(true){if(Date.now()>deadline)throw Error('İşlem çok uzun sürdü. Hizmeti kontrol et.');await new Promise(r=>setTimeout(r,2000));const res=await fetch('/api/jobs/'+job.id);const d=await res.json();if(!res.ok)throw Error(d.error);if(d.state==='failed')throw Error(d.error);if(d.progress>0){$('#progress').value=d.progress;status((source==='upload'?'Dosya dönüştürülüyor… %':'Dosya indiriliyor… %')+Math.round(d.progress))}if(d.state==='complete'){$('#progress').value=100;status('Dosyan hazır. Cihazına kaydedebilirsin.');$('#save').href='/api/files/'+job.id;$('#save').textContent=selectedFormat.toUpperCase()+' dosyasını kaydet';$('#save').hidden=false;break}}}catch(err){status(err.message,true);$('#progress-wrap').hidden=true}finally{lock(false)}};
setKind('video');setSource('upload');
